VALUES ('蓝芯算力', NULL, 'semiconductor', 'design', false, 'B 轮', NULL, NULL, NULL, '2026-10', '{"name":"蓝芯算力","industry":"semiconductor","seg":"design","listed":false,"desc":"高性能 RISC-V + AI 融合架构服务器 CPU 芯片设计企业，2023 年 5 月成立于深圳南山，由前字节跳动圣迭戈办公室 RISC-V 与服务器芯片项目负责人卢山创立。首创 RISC-V 通用计算与 AI 智能计算单芯片原生融合路线，主打 LX500 智算服务器 CPU（48 核异构，32 性能核 + 16 能效核，片内集成 75 TOPS INT8 算力），2026 年 2 月一次性流片成功并点亮、启动 Linux，同年 7 月搭载 LX500 的量产服务器在联想联宝工厂下线，与联想共建 RISC-V+AI 智通融合 CPU 联合创新实验室。","round":"B 轮","lastFunding":"2026-10","latestFunding":"2026 年 10 月完成 B 轮系列融资，合计规模近 20 亿元人民币；深创投、华控基金、隆湫资本等老股东追加，苏国投、苏创投、兆易创新、太平科创、同创伟业、国香资本、建银国际、粤科金融、九坤创投等新股东入场。资金用于 RISC-V 服务器 CPU 量产落地、AI 异构处理器迭代与云服务商/运营商/金融客户通用算力方案拓展。","latestTech":"LX500 全球首款 RISC-V 与 AI 智通融合服务器 CPU，48 核自研异构架构（32 性能核 + 16 能效核），片内集成 75 TOPS INT8 算力引擎，通过统一内存架构消除 CPU-GPU 数据搬移损耗，单芯片即可运行大模型推理；首批支持 RVA23 标准的 RISC-V 服务器芯片厂商之一。","tech":[{"date":"2026-02","title":"LX500 一次性流片成功并点亮","kind":"流片","desc":"成功启动 Linux 操作系统，验证 RISC-V + AI 融合架构可行性。"},{"date":"2026-05","title":"中国移动云能力中心全栈融合方案适配","kind":"生态","desc":"LX500 亮相移动云大会，完成 RISC-V + BC-LINUX 全栈融合方案适配。"},{"date":"2026-07","title":"搭载 LX500 的量产服务器下线","kind":"量产","desc":"在联想联宝工厂正式下线，并与联想成立 RISC-V+AI 智通融合 CPU 联合创新实验室。"}],"funding":[{"date":"2026-10","round":"B 轮","amount":"近 20 亿元（B 轮系列合计）","inv":"老股东追加：深创投 / 华控基金 / 隆湫资本；新增：苏国投 / 苏创投 / 兆易创新 / 太平科创 / 同创伟业 / 国香资本 / 建银国际 / 粤科金融 / 九坤创投","investors":"深创投 · 华控基金 · 隆湫资本（老股东追加）· 苏国投 · 苏创投 · 兆易创新 · 太平科创 · 同创伟业 · 国香资本 · 建银国际 · 粤科金融 · 九坤创投"},{"date":"2026-07","round":"Pre-B 轮","amount":"超 3 亿元","inv":"隆湫资本（独家投资）","investors":"隆湫资本（独家）"},{"date":"2026-08","round":"Pre-B 轮（追加）","amount":"未披露","inv":"未披露","investors":"未披露"},{"date":"2026-03","round":"A / A+ / A++ 轮","amount":"数亿元（连续完成）","inv":"未完整披露（投前估值超 1 亿美元）","investors":"未完整披露"},{"date":"2025","round":"Pre-A 及 Pre-A+ 轮","amount":"数亿元","inv":"未完整披露","investors":"未完整披露"},{"date":"2024-12","round":"Pre-A 轮","amount":"未披露","inv":"未披露","investors":"未披露"},{"date":"2023-12","round":"天使轮","amount":"未披露","inv":"未披露","investors":"未披露"}],"investorsStructured":[{"name":"深创投","role":"follow","round":"B 轮","date":"2026-10","kind":"gov","note":"老股东追加投资"},{"name":"华控基金","role":"follow","round":"B 轮","date":"2026-10","kind":"pe","note":"老股东追加投资"},{"name":"隆湫资本","role":"follow","round":"B 轮","date":"2026-10","kind":"vc","note":"老股东追加；另独家投资 Pre-B 轮超 3 亿元"},{"name":"苏国投","role":"follow","round":"B 轮","date":"2026-10","kind":"gov","note":"江苏省国信集团旗下"},{"name":"苏创投","role":"follow","round":"B 轮","date":"2026-10","kind":"gov","note":"苏州创新投资集团"},{"name":"兆易创新","role":"strategic","round":"B 轮","date":"2026-10","kind":"cvc","note":"存储芯片上市公司产业资本"},{"name":"太平科创","role":"follow","round":"B 轮","date":"2026-10","kind":"pe","note":"太平资产旗下科创投资平台"},{"name":"同创伟业","role":"follow","round":"B 轮","date":"2026-10","kind":"vc"},{"name":"国香资本","role":"follow","round":"B 轮","date":"2026-10","kind":"vc"},{"name":"建银国际","role":"follow","round":"B 轮","date":"2026-10","kind":"pe","note":"建设银行旗下投行平台"},{"name":"粤科金融","role":"follow","round":"B 轮","date":"2026-10","kind":"gov","note":"广东省属科技金融集团"},{"name":"九坤创投","role":"follow","round":"B 轮","date":"2026-10","kind":"vc"}],"executives":[{"name":"卢山","title":"创始人、法定代表人","role":"management","bio":"清华大学自动化系本科，美国波士顿大学电气与计算机工程博士；曾任职英特尔、高通，2019 年加入字节跳动圣迭戈芯片团队负责 RISC-V 架构及服务器芯片，2023 年 5 月离职创业。"}],"note":"2026-10-14 湾芯展（深圳）期间披露，此前 10-12 由南方都市报首报。总部深圳南山，在北京、上海、西安、香港设分支机构，苏州设研发中心。2025 年获深圳市「潜在独角兽企业」称号。"}'::jsonb, now())
