INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at)
VALUES ('星火辰光', NULL, 'semiconductor', 'design', false, '天使轮', NULL, NULL, NULL, '2026-10', '{"name":"星火辰光","industry":"semiconductor","seg":"design","listed":false,"desc":"Micro-LED 光互连芯片研发企业，2026 年 9 月 4 日成立于北京，聚焦 Micro-LED 外延生长与高速芯片设计，重点面向 AI 与高性能计算场景中芯片间、计算与存储间的高速低功耗数据交换需求。公司与天津元旭半导体、清华大学开展三方产学研联合研发，分工覆盖外延优化、芯片制备与系统测试验证；经营范围覆盖集成电路芯片设计、半导体器件专用设备制造、光电子器件制造与销售。","round":"天使轮","lastFunding":"2026-10","latestFunding":"2026 年 10 月完成天使轮（首轮）融资，由红杉中国领投、三安光电跟投，云岫资本担任后续轮次独家财务顾问；金额未披露。","latestTech":"Micro-LED 光互连芯片样品在 500A/cm² 电流密度下 -3dB 带宽可达 3.5GHz；采用多通道中低速并行传输模式（「汇细流成江海」）替代少数超高速率通道思路，面向短距传输场景，与现有光源技术错位互补。","tech":[{"date":"2026-10","title":"Micro-LED 光互连芯片样品测试验证通过","kind":"研发","desc":"联合元旭半导体、清华大学完成阶段验证，500A/cm² 电流密度下 -3dB 带宽达 3.5GHz，为驱动电路、接收终端、光学耦合匹配优化提供实测数据。"}],"funding":[{"date":"2026-10","round":"天使轮（首轮）","amount":"未披露","inv":"领投：红杉中国；跟投：三安光电；财务顾问：云岫资本","investors":"红杉中国（领投）· 三安光电"}],"investorsStructured":[{"name":"红杉中国","role":"lead","round":"天使轮","date":"2026-10","kind":"vc","note":"首轮领投"},{"name":"三安光电","role":"strategic","round":"天使轮","date":"2026-10","kind":"cvc","note":"LED/Micro-LED 芯片上市公司产业跟投，业务协同"}],"note":"成立仅 1 个多月即完成首轮融资；技术路线依附 Micro-LED 产业链，与元旭半导体（巨量转移、玻璃基集成光电封装）深度绑定。"}'::jsonb, now())
