INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at)
VALUES ('芯百特微电子', NULL, 'semiconductor', 'design', false, 'C 轮', NULL, NULL, NULL, '2026-10', '{"name":"芯百特微电子","industry":"semiconductor","seg":"design","listed":false,"desc":"高性能射频芯片研发设计企业，2018 年 10 月成立于无锡惠山经济开发区，采用 Fabless 模式，主营射频前端芯片（GaN/GaAs 功放、滤波器、UWB FEM 等），面向 5G、WiFi、物联网等领域。公司在上海、深圳、西安、成都、中国香港设有分部及办事处，自主研发近百款芯片中已有 50 余款实现量产，获国家级专精特新「小巨人」企业资质。","round":"C 轮","lastFunding":"2026-10","latestFunding":"2026 年 10 月完成 C 轮融资金额近亿元人民币，由新引擎基金投资。","latestTech":"覆盖 GaN 宽带高功率射频功放、GaN 毫米波功率放大器自适应偏置温度补偿、声波滤波器设计、GaAs 逻辑电路与芯片等方向；2022 年 UWB FEM 产品获中国半导体投资联盟年度优秀创新产品奖。","tech":[{"date":"2026-09","title":"GaN 毫米波功率放大器自适应偏置温度补偿专利公开","kind":"专利"},{"date":"2026-08","title":"声波滤波器设计方法与系统专利公开","kind":"专利"},{"date":"2026-07","title":"GaAs 逻辑电路和芯片发明专利授权","kind":"专利"},{"date":"2026-07","title":"入选 2026 中国潜在独角兽榜单","kind":"荣誉"}],"funding":[{"date":"2026-10","round":"C 轮","amount":"近亿元","inv":"新引擎基金","investors":"新引擎基金"},{"date":"2025-01","round":"B 轮","amount":"未披露","inv":"宁波天龙电子 / 元禾控股系主体","investors":"宁波天龙电子 · 元禾控股"},{"date":"2023-01","round":"A 轮","amount":"未披露","inv":"宁波天龙电子 / 元禾控股","investors":"宁波天龙电子 · 元禾控股"}],"investorsStructured":[{"name":"新引擎基金","role":"lead","round":"C 轮","date":"2026-10","kind":"vc","note":"C 轮独家投资方"},{"name":"宁波天龙电子","role":"follow","round":"A 轮","date":"2023-01","kind":"cvc","note":"上市公司产业资本，2023 年 A 轮首次投资"},{"name":"元禾控股","role":"follow","round":"A 轮","date":"2023-01","kind":"vc"}],"executives":[{"name":"张海涛","title":"创始人、CEO、法定代表人","role":"management","bio":"清华大学电子学系学士、硕士，加州大学电子工程博士；InGaP/GaAs HBT 移动通讯领域国际知名技术专家；2022 年获工信部国家级人才资质，西安电子科技大学特聘教授。"}],"note":"企查查显示累计融资 6 次，最新一轮为 B+ 轮后进入 C 轮阶段；2026-09 投资绍兴芯百越微电子有限公司（持股 100%）设立子公司。"}'::jsonb, now())
