INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at)
VALUES ('扑浪量子', NULL, 'semiconductor', 'material', false, 'A 轮', NULL, NULL, NULL, '2026-10', '{"name":"扑浪量子","industry":"semiconductor","seg":"material","listed":false,"desc":"量子点纳米新材料及其应用研发企业，2021 年 5 月成立于深圳，国家级专精特新「小巨人」企业，由北京大学本硕、香港科技大学博士张志宽领衔（曾任聚飞光电 CTO），与南方科技大学讲席教授、俄罗斯科学院外籍院士孙小卫共同创业。掌握量子点全链条技术，推出量子点扩散板、无阻隔膜 PET 量子点膜、量子点光刻胶等新型显示材料，并延伸至半导体薄膜工艺设备。","round":"A 轮","lastFunding":"2026-10","latestFunding":"2026 年 10 月完成 A 轮融资，由中信建投资本投资；金额未披露。资金主要用于高端量子点显示应用产品产能扩建与核心技术研发。","latestTech":"量子点全链条技术（材料合成 → 表面改性 → 膜材制备 → 器件应用）；已申请高相容性量子点表面改性方法、无表面活性剂二氧化硅包覆量子点方法等发明专利，推进高端量子点显示与电致发光量子点显示器件。","tech":[{"date":"2026-09","title":"高相容性量子点表面改性方法专利公开","kind":"专利"},{"date":"2026-09","title":"无表面活性剂的二氧化硅包覆量子点方法专利公开","kind":"专利"}],"funding":[{"date":"2026-10","round":"A 轮","amount":"未披露","inv":"中信建投资本","investors":"中信建投资本"},{"date":"2026-09","round":"Pre-A+ 轮","amount":"未披露","inv":"中信建投资本","investors":"中信建投资本"},{"date":"2022-10","round":"Pre-A 轮","amount":"数千万元","inv":"东方嘉富 / 北汽产投 / 苏州毅和基金","investors":"东方嘉富 · 北汽产投 · 苏州毅和基金"},{"date":"2022-02","round":"天使轮","amount":"5000 万元","inv":"中科创星 / 拓金资本","investors":"中科创星 · 拓金资本"}],"investorsStructured":[{"name":"中信建投资本","role":"lead","round":"A 轮","date":"2026-10","kind":"pe","note":"中信建投证券旗下私募股权投资平台，A 轮独家投资；亦参与 Pre-A+ 轮"},{"name":"东方嘉富","role":"follow","round":"Pre-A 轮","date":"2022-10","kind":"vc"},{"name":"北汽产投","role":"strategic","round":"Pre-A 轮","date":"2022-10","kind":"cvc","note":"北汽集团产业资本，车载显示场景协同"},{"name":"苏州毅和基金","role":"follow","round":"Pre-A 轮","date":"2022-10","kind":"vc"},{"name":"中科创星","role":"lead","round":"天使轮","date":"2022-02","kind":"vc"},{"name":"拓金资本","role":"lead","round":"天使轮","date":"2022-02","kind":"vc"}],"executives":[{"name":"张志宽","title":"创始人、CEO","role":"management","bio":"北京大学本硕、香港科技大学博士，曾任聚飞光电 CTO；与南方科技大学讲席教授、俄罗斯科学院外籍院士孙小卫共同创业。"}],"note":"全球第一家大批量实现前装车载量子点膜量产的公司，全球车载量子点膜市占率超 70%，累计为极氪 7X、蔚来、大众、奥迪等项目出货 300 万台；产品独家供应联想拯救者 9000K、华硕 ROG 系列笔记本，并进入 LG、京东方、TCL、华星光电、Meta、Sony 等供应链。"}'::jsonb, now())
